import React from "react";
import styled from "styled-components";

const TableContainer = styled.div`
  width: 100%;
  background: white;
  padding: 20px;
  border-radius: 8px;
  box-shadow: 0px 4px 6px rgba(0, 0, 0, 0.1);
  margin-top: 20px;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  overflow-x: auto; /* Cho phép cuộn ngang nếu bảng quá rộng */
`;

const Title = styled.h3`
  font-size: 32px;
  font-weight: bold;
  margin-bottom: 20px;
  text-align: center;
`;

const TableWrapper = styled.div`
  width: 100%;
  max-width: 100%;
  overflow-x: auto;
`;

const Table = styled.table`
  width: auto; /* Điều chỉnh bảng theo nội dung */
  min-width: 100%;
  border-collapse: collapse;
`;

const Th = styled.th`
  background: #d6d6d6;
  color: black;
  padding: 10px;
  text-align: left;
  white-space: nowrap; /* Giữ nội dung không bị xuống dòng */
`;

const Td = styled.td`
  border: 1px solid #ddd;
  padding: 10px;
  white-space: nowrap;
`;

const VirulenceTable = ({ data }) => {
  const headers = [
    "Index", "Sequence", "Gene", "Start", "Stop", "Strand", "Identity (%)", "Coverage (%)", "Accession", "Nucleic"
  ];

  // Chuyển đổi dữ liệu thành bảng
  const body = data.map((item, index) => [
    index + 1, // Số thứ tự bắt đầu từ 1
    item.sequence,
    item.gene,
    item.start,
    item.stop,
    item.strand,
    item.identity,
    item.coverage,
    item.accession,
    item.product
  ]);

  return (
    <TableContainer>
      <Title>Virulence Data</Title>
      <TableWrapper>
        <Table>
          <thead>
            <tr>
              {headers.map((header, index) => (
                <Th key={index}>{header}</Th>
              ))}
            </tr>
          </thead>
          <tbody>
            {body.map((row, rowIndex) => (
              <tr key={rowIndex}>
                {row.map((cell, cellIndex) => (
                  <Td key={cellIndex}>{cell}</Td>
                ))}
              </tr>
            ))}
          </tbody>
        </Table>
      </TableWrapper>
    </TableContainer>
  );
};

export default VirulenceTable;
